-- Security hardening: FK indexes applied 2025-07-24
-- This project uses drizzle-kit push (no migration files generated by default).
-- This file documents the indexes applied directly to the running database
-- and matches the index definitions in lib/db/src/schema/{shield,billing}.ts.
-- Re-running these is idempotent (CREATE INDEX IF NOT EXISTS).

-- connected_accounts
CREATE INDEX IF NOT EXISTS connected_accounts_user_id_idx ON connected_accounts(user_id);
CREATE INDEX IF NOT EXISTS connected_accounts_platform_idx ON connected_accounts(platform);

-- media_items (FK: account_id -> connected_accounts.id)
CREATE INDEX IF NOT EXISTS media_items_account_id_idx ON media_items(account_id);

-- scan_jobs
CREATE INDEX IF NOT EXISTS scan_jobs_user_id_idx ON scan_jobs(user_id);
CREATE INDEX IF NOT EXISTS scan_jobs_status_idx ON scan_jobs(status);
CREATE INDEX IF NOT EXISTS scan_jobs_user_status_idx ON scan_jobs(user_id, status);

-- threats
CREATE INDEX IF NOT EXISTS threats_user_id_idx ON threats(user_id);
CREATE INDEX IF NOT EXISTS threats_scan_job_id_idx ON threats(scan_job_id);
CREATE INDEX IF NOT EXISTS threats_threat_actor_id_idx ON threats(threat_actor_id);
CREATE INDEX IF NOT EXISTS threats_user_resolved_idx ON threats(user_id, resolved);
CREATE INDEX IF NOT EXISTS threats_user_severity_idx ON threats(user_id, severity);
CREATE INDEX IF NOT EXISTS threats_created_at_idx ON threats(created_at);

-- api_cost_log
CREATE INDEX IF NOT EXISTS api_cost_log_user_id_idx ON api_cost_log(user_id);

-- device_push_tokens
CREATE INDEX IF NOT EXISTS device_push_tokens_user_id_idx ON device_push_tokens(user_id);

-- identity_embeddings
CREATE INDEX IF NOT EXISTS identity_embeddings_user_id_idx ON identity_embeddings(user_id);

-- api_keys (FK: user_id -> users.id)
CREATE INDEX IF NOT EXISTS api_keys_user_id_idx ON api_keys(user_id);

-- webhooks (FK: api_key_id -> api_keys.id)
CREATE INDEX IF NOT EXISTS webhooks_api_key_id_idx ON webhooks(api_key_id);

-- webhook_delivery_log (FK: webhook_id -> webhooks.id)
CREATE INDEX IF NOT EXISTS webhook_delivery_log_webhook_id_idx ON webhook_delivery_log(webhook_id);
CREATE INDEX IF NOT EXISTS webhook_delivery_log_status_retry_idx ON webhook_delivery_log(status, next_retry_at);

-- api_key_rate_limits (FK: key_id -> api_keys.id)
CREATE INDEX IF NOT EXISTS api_key_rate_limits_key_window_idx ON api_key_rate_limits(key_id, window_start);

-- user_photo_hashes (FK: account_id -> connected_accounts.id)
CREATE INDEX IF NOT EXISTS user_photo_hashes_account_id_idx ON user_photo_hashes(account_id);

-- phash_feedback
CREATE INDEX IF NOT EXISTS phash_feedback_user_id_idx ON phash_feedback(user_id);
CREATE INDEX IF NOT EXISTS phash_feedback_threat_id_idx ON phash_feedback(threat_id);

-- scheduled_notifications (billing schema)
CREATE INDEX IF NOT EXISTS scheduled_notifs_user_id_idx ON scheduled_notifications(user_id);
CREATE INDEX IF NOT EXISTS scheduled_notifs_fire_at_idx ON scheduled_notifications(fire_at, fired);

-- cancellation_feedback (billing schema)
CREATE INDEX IF NOT EXISTS cancellation_feedback_user_id_idx ON cancellation_feedback(user_id);

-- messages (FK: conversation_id -> conversations.id)
CREATE INDEX IF NOT EXISTS messages_conversation_id_idx ON messages(conversation_id);
